module shift_reg_universal (
    input  wire             clk,
    input  wire             rst,
    input  wire [1:0]       mode,      // 00: Hold, 01: Shift Left, 10: Shift Right, 11: Parallel Load
    input  wire             sin_left,  // Serial input for shift left
    input  wire             sin_right, // Serial input for shift right
    input  wire [3:0]      d_in,      // Parallel data input
    output reg  [3:0]      q_out      // Parallel data output
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q_out <= 4'd0;
        end else begin
            case (mode)
                2'b00: q_out <= q_out;
                2'b01: q_out <= {q_out[2:0], sin_left};
                2'b10: q_out <= {sin_right, q_out[3:1]};
                2'b11: q_out <= d_in;
            endcase
        end
    end

endmodule
